// ─── File: src/test/java/com/bank/pinning/PinningTest.java ───
package com.bank.pinning;

import org.junit.jupiter.api.Test;
import java.util.concurrent.locks.ReentrantLock;
import static org.assertj.core.api.Assertions.*;

class PinningTest {

    @Test void reentrantLockDoesNotPin() throws Exception {
        ReentrantLock lock = new ReentrantLock();
        Thread vt = Thread.startVirtualThread(() -> {
            lock.lock();
            try {
                // Simulated I/O — virtual thread can unmount here
                try { Thread.sleep(10); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            } finally {
                lock.unlock();
            }
        });
        vt.join();
        assertThat(vt.isVirtual()).isTrue();
    }

    @Test void reentrantLockSupportsTryLock() {
        ReentrantLock lock = new ReentrantLock();
        lock.lock();
        try {
            boolean acquired = lock.tryLock();  // non-blocking attempt
            assertThat(acquired).isTrue();  // same thread can reenter (reentrant!)
            lock.unlock();
        } finally {
            lock.unlock();
        }
    }
}
