// File: src/test/java/com/bank/java8/PinningTest.java
package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.concurrent.locks.ReentrantLock;
import static org.assertj.core.api.Assertions.assertThat;

class PinningTest {

    private final ReentrantLock lock = new ReentrantLock();  // VT-friendly, no pinning
    private int balance = 1000;

    void debit(int amt) {
        lock.lock();
        try { balance -= amt; }        // short critical section, NO blocking I/O inside
        finally { lock.unlock(); }
    }

    @Test
    void reentrantLockAvoidsPinning() {
        debit(300);
        debit(200);
        assertThat(balance).isEqualTo(500);
    }
}
